<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
const form = useForm({ title: '', description: '', program: '', academic_year: '', category: '', technology: '', tags: '', files: [] });
function submit() { form.post('/upload'); }
</script>
<template>
    <Head title="Upload academic work" /><AppLayout><div class="mx-auto max-w-4xl p-6 lg:p-10"><Link href="/dashboard" class="text-sm font-semibold text-olfu">← Back to dashboard</Link><h1 class="mt-4 text-3xl font-bold">Upload academic work</h1><p class="mt-2 text-slate-500">Your files stay private until reviewed by the Research Coordinator.</p>
        <form class="mt-8 rounded-2xl border border-slate-200 bg-white p-6 lg:p-8" @submit.prevent="submit"><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-semibold md:col-span-2">Project title<input v-model="form.title" class="input" required /></label><label class="text-sm font-semibold md:col-span-2">Description<textarea v-model="form.description" class="input" rows="4" required></textarea></label><label class="text-sm font-semibold">Program<input v-model="form.program" class="input" placeholder="BSIT, BSCS..." required /></label><label class="text-sm font-semibold">Academic year<input v-model="form.academic_year" class="input" placeholder="2025-2026" required /></label><label class="text-sm font-semibold">Category<input v-model="form.category" class="input" placeholder="Capstone project" required /></label><label class="text-sm font-semibold">Technology<input v-model="form.technology" class="input" placeholder="Laravel, Vue..." /></label><label class="text-sm font-semibold md:col-span-2">Tags <span class="font-normal text-slate-400">(comma separated)</span><input v-model="form.tags" class="input" /></label><label class="rounded-xl border-2 border-dashed border-slate-200 p-6 text-center text-sm font-semibold md:col-span-2">Project files<input type="file" class="mt-3 block w-full text-sm" multiple required @input="form.files = [...$event.target.files]" /><span class="mt-2 block text-xs font-normal text-slate-400">PDF, Office files, ZIP, images and common source code · max 50 MB each</span></label></div><div class="mt-8 flex justify-end"><button class="btn-primary" :disabled="form.processing">Submit for moderation</button></div></form></div></AppLayout>
</template>
